Here is the recipe JSON:
{
  "recipe_name": "Classic Cheese Pizza",
  "ingredients": [
    "1 1/2 cups warm water",
    "1 tablespoon sugar",
    "2 teaspoons active dry yeast",
    "3 1/2 cups all-purpose flour",
    "1 teaspoon salt",
    "2 tablespoons olive oil",
    "1/2 cup pizza sauce",
    "2 cups shredded mozzarella cheese",
    "1/4 cup grated Parmesan cheese",
    "Fresh basil leaves"
  ],
  "steps": [
    {
      "step_number": 1,
      "instruction": "In a large mixing bowl, combine warm water, sugar, and yeast. Let it sit for 5-7 minutes until yeast is activated.",
      "time": "5-7 minutes",
      "tip": "Make sure the water is not too hot, as it can kill the yeast."
    },
    {
      "step_number": 2,
      "instruction": "Add flour, salt, and olive oil to the bowl. Mix until a dough forms.",
      "time": "5 minutes",
      "tip": "You can use a stand mixer with a dough hook attachment to make the process easier."
    },
    {
      "step_number": 3,
      "instruction": "Knead the dough on a floured surface for 5-7 minutes until it becomes smooth and elastic.",
      "time": "5-7 minutes",
      "tip": "You can also use a bread machine to knead the dough."
    },
    {
      "step_number": 4,
      "instruction": "Place the dough in a greased bowl, cover it with a damp cloth, and let it rise in a warm place for 1-2 hours until it doubles in size.",
      "time": "1-2 hours",
      "tip": "Make sure the dough is in a warm, draft-free place to help it rise."
    },
    {
      "step_number": 5,
      "instruction": "Preheat the oven to 425\u00b0F (220\u00b0C). Punch down the dough and roll it out into a circle or rectangle shape.",
      "time": "5 minutes",
      "tip": "You can use a pizza stone or baking sheet to bake the pizza."
    },
    {
      "step_number": 6,
      "instruction": "Spread the pizza sauce over the dough, leaving a small border around the edges.",
      "time": "2 minutes",
      "tip": "You can use homemade or store-bought pizza sauce."
    },
    {
      "step_number": 7,
      "instruction": "Sprinkle the shredded mozzarella cheese and grated Parmesan cheese over the sauce.",
      "time": "2 minutes",
      "tip": "You can also add other toppings like pepperoni, mushrooms, or bell peppers."
    },
    {
      "step_number": 8,
      "instruction": "Bake the pizza in the preheated oven for 15-20 minutes until the crust is golden brown and the cheese is melted and bubbly.",
      "time": "15-20 minutes",
      "tip": "Keep an eye on the pizza to make sure it doesn't overcook."
    }
  ]
}
